"use server";

import { revalidatePath } from "next/cache";

// In a real application, this would be stored in a database
// For this example, we'll use a simple in-memory store
let userNotificationPreference = true;

export async function toggleNotificationPreference() {
  try {
    // Toggle the notification preference
    userNotificationPreference = !userNotificationPreference;

    // Revalidate the current page to refresh without redirecting
    revalidatePath("/");

    return {
      success: true,
      message: "Notification preference updated",
      notificationsEnabled: userNotificationPreference
    };
  } catch (error) {
    console.error("Error toggling notification preference:", error);
    return {
      success: false,
      message: "Failed to update notification preference",
      notificationsEnabled: userNotificationPreference
    };
  }
}

export async function getNotificationPreference() {
  return {
    notificationsEnabled: userNotificationPreference
  };
}

